# Code generated by Claude
"""
Tests of the bench stance regions (src/bench_stance.py) with the F1 to F3 filters, on the test scene (beaker and hotplate 14 cm from the bench edge). Needs the simulator model and EGL.

    MUJOCO_GL=egl python experiments/bench_stance_test.py

1. One task-point builder: full_check.task_points is src/task_points.task_points, and path_offsets gives the standoff, over and lift points of a bin (lookups only, no IK).
2. widest_run: the widest run of consecutive heights per cell and its middle.
3. TASK_CFG's stance has a nonzero count for both objects after F1 to F3 (path points, camera framing and grippers, robot-hides-target, zombie clearance to the object, furniture masks).
4. Agreement with the finder at a grid of spots in and around +-6 cm of TASK_CFG's stance, at three pedestal heights: the region's verdict (both objects nonzero) against the finder's (the quick search's
   12 task points reachable by any bin AND the stance requirements of src/stance_checks.py). Disagreements are printed, not hidden; the test only requires the centre spot to agree and the
   region not to pass more than one in four of the spots the finder rejects (the region may be looser: no IK path check, no error stances).
5. The occlusion approximation against the finder's pixel measure at TASK_CFG's stance and at the stance the overlay picks (printed; the sampled share must not be below the pixel share by more than 2 points).
"""

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from experiments.bench_stance_validate import scene_objects  # noqa: E402
from src import bench_stance as bs  # noqa: E402
from src.furniture_map import FurnitureMap  # noqa: E402
from src.stance_checks import StanceChecks  # noqa: E402
from src.stance_finder import region_scores, robot_geometry  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BENCH_STANCE_CFG, TASK_CFG  # noqa: E402
from src.task_points import path_offsets, task_points  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main():
    print("\n1. the one task-point builder")
    import src.full_check as fcm
    check("full_check.task_points is the shared builder", fcm.task_points is task_points)
    off = path_offsets(0, [1.0, 1.02], 0.96)
    check("path_offsets: standoff 12 cm back, over 20 cm above the surface, lift 10 cm above the band's middle",
          [o[0] for o in off] == ["standoff", "over", "lift"] and abs(off[0][1] + 0.12) < 1e-9 and abs(off[1][3] - 1.16) < 1e-9 and abs(off[2][3] - 1.11) < 1e-9, f"{off}")
    off3 = path_offsets(3, [1.0], 0.96)
    check("path_offsets for bin 3 (the hand moves to the left) puts the standoff 12 cm to the right", abs(off3[0][1]) < 1e-9 and abs(off3[0][2] + 0.12) < 1e-9, f"{off3[0]}")

    print("\n2. widest_run")
    v = np.zeros((8, 1, 3), bool)
    v[1:3, 0, 0] = True
    v[3:8, 0, 1] = True
    v[0:2, 0, 2] = True
    v[4:7, 0, 2] = True
    w, lo, hi = bs.widest_run(v)
    check("widest run per cell: (2 at 1-2), (5 at 3-7), (3 at 4-6: the wider of two)", w[0].tolist() == [2, 5, 3] and lo[0].tolist() == [1, 3, 4] and hi[0].tolist() == [2, 7, 6], f"{w[0].tolist()} {lo[0].tolist()} {hi[0].tolist()}")

    sim = load_task()
    m, d = sim.model, sim.data
    rg = robot_geometry(m)
    chk = StanceChecks(m, d, rg["base_z"])
    qs = bs.pedestal_commands()
    yaw = TASK_CFG["staging_yaw"]
    x0, y0 = TASK_CFG["staging_xy"]
    cams = bs.camera_poses(m, qs, chk=chk, ref_stance=(x0, y0, yaw), cache_dir=BENCH_STANCE_CFG["cache_dir"])
    maps = bs.load_maps("data/reach_map", sides=("left",))
    objs = scene_objects(m, d)
    n, t = bs.bench_frame(yaw)
    regs = {o["name"]: bs.get_region(maps, rg, cams, o["depth"], bs.spec_in_base_frame(o, yaw, rg["base_z"])) for o in objs}

    def verdict(x, y, qi):
        out = []
        for o in objs:
            reg = regs[o["name"]]
            dxy = np.asarray(o["xy"]) - np.array([x, y])
            ib, io = int(round((float(dxy @ n) - reg["b"][0]) / 0.01)), int(round((float(dxy @ t) - reg["o"][0]) / 0.01))
            out.append(int(bs.counts(reg)[qi, ib, io]))
        return out

    print("\n3. TASK_CFG's stance")
    qi0 = int(np.argmin(abs(np.array(qs) - TASK_CFG["pedestal_q"])))
    c = verdict(x0, y0, qi0)
    check("the region has a nonzero count for both objects at TASK_CFG's stance and pedestal", min(c) > 0, f"beaker {c[0]}, hotplate {c[1]} at q {qs[qi0]}")

    print("\n4. agreement with the finder around TASK_CFG's stance")
    furn = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    fpts = [dict(p, arm="left") for p in task_points(m, d)]
    FX, FY, FS = region_scores(fpts, maps, furn, rg, yaw, qs)
    fs = FS["left"]
    rows, dis, rej, rej_pass = [], [], 0, 0
    for dx in (-0.06, -0.03, 0.0, 0.03, 0.06):
        for dy in (-0.06, 0.0, 0.06):
            x, y = x0 + dx, y0 + dy
            iyf, ixf = int(np.argmin(abs(FY[:, 0] - y))), int(np.argmin(abs(FX[0] - x)))
            for q in (0.08, 0.12, 0.15):
                qi = int(np.argmin(abs(np.array(qs) - q)))
                fq = fs[qi, iyf, ixf] > 0
                req = chk.requirements((x, y, yaw, qs[qi]))
                fin = bool(fq and req["ok"])
                cnt = verdict(x, y, qi)
                reg_ok = min(cnt) > 0
                rows.append((x, y, qs[qi], fin, reg_ok, fq, req["failed"], cnt))
                if fin != reg_ok:
                    dis.append(rows[-1])
                if not fin:
                    rej += 1
                    rej_pass += reg_ok
    for r in dis:
        print(f"    disagreement at ({r[0]:.2f}, {r[1]:.3f}) q {r[2]:.3f}: finder {'passes' if r[3] else 'fails'} (quick search {'ok' if r[5] else 'no'}, requirements failed {r[6]}), region {'passes' if r[4] else 'fails'} (counts {r[7]})")
    print(f"    {len(rows)} (spot, height) cases: {len(rows) - len(dis)} agree, {len(dis)} disagree; the finder rejects {rej}, the region passes {rej_pass} of those")
    centre = [r for r in rows if abs(r[0] - x0) < 1e-9 and abs(r[1] - y0) < 1e-9 and abs(r[2] - 0.15) < 1e-9][0]
    check("the centre spot at TASK_CFG's pedestal: both pass", centre[3] and centre[4])
    check("the region passes at most one in four of the cases the finder rejects", rej == 0 or rej_pass <= 0.25 * rej, f"{rej_pass} of {rej}")

    print("\n5. the occlusion approximation")
    import json
    best = json.load(open("data/bench_stance_last.json"))["best"] if Path("data/bench_stance_last.json").exists() else None
    stances = [("TASK_CFG", x0, y0, TASK_CFG["pedestal_q"])] + ([("overlay's pick", best["xy"][0], best["xy"][1], best["q"])] if best else [])
    for name, x, y, q in stances:
        occ = chk.occlusion((x, y, yaw, q))
        qi = int(np.argmin(abs(np.array(qs) - q)))
        ok = True
        for o, key in zip(objs, ("beaker", "hotplate")):
            sp = bs.spec_in_base_frame(o, yaw, rg["base_z"])
            dxy = np.asarray(o["xy"]) - np.array([x, y])
            h = float(bs.hidden_fraction(cams, cams["sil"], qi, np.array([float(dxy @ n)]), np.array([float(dxy @ t)]), sp["samples"])[0])
            fin = occ[f"{key}_hidden_frac"]
            print(f"    {name}: {key} hidden: finder (pixels) {100 * fin:.1f} %, region (samples) {100 * h:.1f} %")
            ok &= h >= fin - 0.02
        check(f"{name}: the sampled share is not below the pixel share by more than 2 points", ok)

    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
